import type { Metadata } from "next";
import Link from "next/link";
import { BlogClient } from "@/components/site/BlogClient";
import { BLOG_KEYWORDS, breadcrumbSchema, faqSchema, SITE_URL } from "@/lib/seo";
import { fetchPublicBlogs, checkAdminSession } from "@/server/blogs";
import { PublicBlog } from "@/lib/blogs-types";

export async function generateMetadata(): Promise<Metadata> {
  const blogs = await fetchPublicBlogs();
  const total = blogs.length;

  return {
    title: "Web Design, AI Automation & Custom Software Blog | Hire NovaMind AI",
    description:
      total > 0
        ? `Looking to hire top developers? Read ${total} expert playbooks on AI automation, high-converting web design, custom ERP/POS software, and SEO strategies for US, UK, UAE, and global clients.`
        : "Looking to hire top developers? Discover proven playbooks on AI automation, high-converting web design, custom ERP/POS software, and SEO for US, UK, UAE, and global clients.",
    keywords: BLOG_KEYWORDS.join(", "),
    openGraph: {
      title: "Web Design, AI Automation & Software Development Blog | NovaMind AI",
      description:
        "Practical playbooks for founders and digital leaders scaling custom software, AI agents, search visibility, and revenue-driving web applications.",
      type: "website",
      url: `${SITE_URL}/blog`,
    },
    twitter: {
      card: "summary_large_image",
    },
  };
}

