export default async function BlogPage() {
  const blogs = await fetchPublicBlogs();
  const isAdminUser = await checkAdminSession();

  return (
    <div className="min-h-screen">
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify(breadcrumbSchema([{ name: "Blog", path: "/blog" }])),
        }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify({
            "@context": "https://schema.org",
            "@type": "Blog",
            name: "NovaMind AI Engineering & Growth Blog",
            url: `${SITE_URL}/blog`,
            description:
              "In-depth guides on custom web design, AI automation, enterprise ERP/POS development, and technical SEO.",
            publisher: { "@id": `${SITE_URL}/#organization` },
          }),
        }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify(faqSchema(blogFaqs)),
        }}
      />

      <BlogClient initialBlogs={blogs} initialIsAdmin={isAdminUser} fallbackPosts={fallbackPosts} blogFaqs={blogFaqs} />
    </div>
  );
}
